with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التنبؤ التشغيلي وإدارة المراكز الجوية','إجراءات التنبؤ اليومية وتسليم المناوبات وإنتاج المنتجات والتنسيق القطاعي وإدارة الجودة واستمرارية الخدمة.',33,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'إجراءات العمل والتحليل اليومي',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التنسيق وإدارة الجودة التشغيلية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('operational-forecast-shift-handover','تسليم المناوبة في مركز التنبؤات','نقل الحالة والقرارات والمهام والمخاطر بين المناوبات.','{"blocks":[{"type":"text","text":"يعالج الدرس تسليم المناوبة في مركز التنبؤات ضمن بيئة مركز أرصاد يعمل على مدار الساعة ويقدم معلومات لقطاعات متعددة."},{"type":"text","text":"الهدف التشغيلي: نقل الحالة والقرارات والمهام والمخاطر بين المناوبات. مع ضمان وضوح المسؤوليات واستمرارية المعلومات وسلامة القرار."},{"type":"text","text":"تحدد بداية الإجراء المسؤوليات والأدوار ومصادر البيانات والمنتج المطلوب والمهلة الزمنية."},{"type":"text","text":"تجمع الحالة من الرصد السطحي والعلوي والرادار والأقمار والنماذج والسجلات التشغيلية."},{"type":"text","text":"تسجل الافتراضات والقيود والسيناريوهات البديلة ومستوى الثقة وأسباب القرار."},{"type":"text","text":"تستخدم قوالب موحدة للمصطلحات والتوقيت والوحدات والمناطق لتقليل الالتباس بين الفرق."},{"type":"text","text":"تطبق مراجعة زميل أو مسؤول مناوبة على المنتجات ذات الأثر العالي قبل إصدارها وفق الإجراء المعتمد."},{"type":"text","text":"تحفظ نسخة مؤرخة من المنتج والبيانات المرجعية وسجل التغييرات لتسهيل التدقيق اللاحق."},{"type":"text","text":"تحدد آلية التصعيد عند ظهور معلومات جديدة أو تعارض بين مصادر البيانات أو تعطل خدمة أساسية."},{"type":"text","text":"تراجع مؤشرات الأداء والالتزام بالوقت وجودة المحتوى ورضا الجهات المستفيدة بصورة دورية."},{"type":"text","text":"مثال تطبيقي: عند تغير مسار حالة جوية، يوثق المتنبئ الدليل الجديد ويحدث السيناريو والمنتج ويبلغ المناوبة والجهات المعنية."},{"type":"callout","text":"الخلاصة: التشغيل الاحترافي يعتمد على إجراء موحد وتواصل موثق ومراجعة مستمرة واستمرارية الخدمة."}]}',2960,50,'["تحديد الأدوار ومصادر المعلومات","إنتاج مخرجات موحدة قابلة للتدقيق","تطبيق المراجعة والتحسين التشغيلي"]','إجراءات العمل والتحليل اليومي'),
('daily-synoptic-briefing','إعداد الإحاطة السينوبتيكية اليومية','تلخيص الحالة الحالية والأنظمة المؤثرة والتطور المتوقع.','{"blocks":[{"type":"text","text":"يعالج الدرس إعداد الإحاطة السينوبتيكية اليومية ضمن بيئة مركز أرصاد يعمل على مدار الساعة ويقدم معلومات لقطاعات متعددة."},{"type":"text","text":"الهدف التشغيلي: تلخيص الحالة الحالية والأنظمة المؤثرة والتطور المتوقع. مع ضمان وضوح المسؤوليات واستمرارية المعلومات وسلامة القرار."},{"type":"text","text":"تحدد بداية الإجراء المسؤوليات والأدوار ومصادر البيانات والمنتج المطلوب والمهلة الزمنية."},{"type":"text","text":"تجمع الحالة من الرصد السطحي والعلوي والرادار والأقمار والنماذج والسجلات التشغيلية."},{"type":"text","text":"تسجل الافتراضات والقيود والسيناريوهات البديلة ومستوى الثقة وأسباب القرار."},{"type":"text","text":"تستخدم قوالب موحدة للمصطلحات والتوقيت والوحدات والمناطق لتقليل الالتباس بين الفرق."},{"type":"text","text":"تطبق مراجعة زميل أو مسؤول مناوبة على المنتجات ذات الأثر العالي قبل إصدارها وفق الإجراء المعتمد."},{"type":"text","text":"تحفظ نسخة مؤرخة من المنتج والبيانات المرجعية وسجل التغييرات لتسهيل التدقيق اللاحق."},{"type":"text","text":"تحدد آلية التصعيد عند ظهور معلومات جديدة أو تعارض بين مصادر البيانات أو تعطل خدمة أساسية."},{"type":"text","text":"تراجع مؤشرات الأداء والالتزام بالوقت وجودة المحتوى ورضا الجهات المستفيدة بصورة دورية."},{"type":"text","text":"مثال تطبيقي: عند تغير مسار حالة جوية، يوثق المتنبئ الدليل الجديد ويحدث السيناريو والمنتج ويبلغ المناوبة والجهات المعنية."},{"type":"callout","text":"الخلاصة: التشغيل الاحترافي يعتمد على إجراء موحد وتواصل موثق ومراجعة مستمرة واستمرارية الخدمة."}]}',2970,50,'["تحديد الأدوار ومصادر المعلومات","إنتاج مخرجات موحدة قابلة للتدقيق","تطبيق المراجعة والتحسين التشغيلي"]','إجراءات العمل والتحليل اليومي'),
('forecast-discussion-and-consensus','اجتماع مناقشة التوقع وبناء الرأي المشترك','دمج الأدلة والنماذج وخبرة المتنبئين.','{"blocks":[{"type":"text","text":"يعالج الدرس اجتماع مناقشة التوقع وبناء الرأي المشترك ضمن بيئة مركز أرصاد يعمل على مدار الساعة ويقدم معلومات لقطاعات متعددة."},{"type":"text","text":"الهدف التشغيلي: دمج الأدلة والنماذج وخبرة المتنبئين. مع ضمان وضوح المسؤوليات واستمرارية المعلومات وسلامة القرار."},{"type":"text","text":"تحدد بداية الإجراء المسؤوليات والأدوار ومصادر البيانات والمنتج المطلوب والمهلة الزمنية."},{"type":"text","text":"تجمع الحالة من الرصد السطحي والعلوي والرادار والأقمار والنماذج والسجلات التشغيلية."},{"type":"text","text":"تسجل الافتراضات والقيود والسيناريوهات البديلة ومستوى الثقة وأسباب القرار."},{"type":"text","text":"تستخدم قوالب موحدة للمصطلحات والتوقيت والوحدات والمناطق لتقليل الالتباس بين الفرق."},{"type":"text","text":"تطبق مراجعة زميل أو مسؤول مناوبة على المنتجات ذات الأثر العالي قبل إصدارها وفق الإجراء المعتمد."},{"type":"text","text":"تحفظ نسخة مؤرخة من المنتج والبيانات المرجعية وسجل التغييرات لتسهيل التدقيق اللاحق."},{"type":"text","text":"تحدد آلية التصعيد عند ظهور معلومات جديدة أو تعارض بين مصادر البيانات أو تعطل خدمة أساسية."},{"type":"text","text":"تراجع مؤشرات الأداء والالتزام بالوقت وجودة المحتوى ورضا الجهات المستفيدة بصورة دورية."},{"type":"text","text":"مثال تطبيقي: عند تغير مسار حالة جوية، يوثق المتنبئ الدليل الجديد ويحدث السيناريو والمنتج ويبلغ المناوبة والجهات المعنية."},{"type":"callout","text":"الخلاصة: التشغيل الاحترافي يعتمد على إجراء موحد وتواصل موثق ومراجعة مستمرة واستمرارية الخدمة."}]}',2980,50,'["تحديد الأدوار ومصادر المعلومات","إنتاج مخرجات موحدة قابلة للتدقيق","تطبيق المراجعة والتحسين التشغيلي"]','إجراءات العمل والتحليل اليومي'),
