('forecast-product-standardization','توحيد قوالب ونشرات التوقعات','بنية المنتج والمصطلحات والوحدات والتوقيت.','{"blocks":[{"type":"text","text":"يعالج الدرس توحيد قوالب ونشرات التوقعات ضمن بيئة مركز أرصاد يعمل على مدار الساعة ويقدم معلومات لقطاعات متعددة."},{"type":"text","text":"الهدف التشغيلي: بنية المنتج والمصطلحات والوحدات والتوقيت. مع ضمان وضوح المسؤوليات واستمرارية المعلومات وسلامة القرار."},{"type":"text","text":"تحدد بداية الإجراء المسؤوليات والأدوار ومصادر البيانات والمنتج المطلوب والمهلة الزمنية."},{"type":"text","text":"تجمع الحالة من الرصد السطحي والعلوي والرادار والأقمار والنماذج والسجلات التشغيلية."},{"type":"text","text":"تسجل الافتراضات والقيود والسيناريوهات البديلة ومستوى الثقة وأسباب القرار."},{"type":"text","text":"تستخدم قوالب موحدة للمصطلحات والتوقيت والوحدات والمناطق لتقليل الالتباس بين الفرق."},{"type":"text","text":"تطبق مراجعة زميل أو مسؤول مناوبة على المنتجات ذات الأثر العالي قبل إصدارها وفق الإجراء المعتمد."},{"type":"text","text":"تحفظ نسخة مؤرخة من المنتج والبيانات المرجعية وسجل التغييرات لتسهيل التدقيق اللاحق."},{"type":"text","text":"تحدد آلية التصعيد عند ظهور معلومات جديدة أو تعارض بين مصادر البيانات أو تعطل خدمة أساسية."},{"type":"text","text":"تراجع مؤشرات الأداء والالتزام بالوقت وجودة المحتوى ورضا الجهات المستفيدة بصورة دورية."},{"type":"text","text":"مثال تطبيقي: عند تغير مسار حالة جوية، يوثق المتنبئ الدليل الجديد ويحدث السيناريو والمنتج ويبلغ المناوبة والجهات المعنية."},{"type":"callout","text":"الخلاصة: التشغيل الاحترافي يعتمد على إجراء موحد وتواصل موثق ومراجعة مستمرة واستمرارية الخدمة."}]}',3010,50,'["تحديد الأدوار ومصادر المعلومات","إنتاج مخرجات موحدة قابلة للتدقيق","تطبيق المراجعة والتحسين التشغيلي"]','إجراءات العمل والتحليل اليومي'),
('weather-map-production-workflow','سير عمل إنتاج الخرائط الجوية','مصادر البيانات والتحليل والإخراج والمراجعة.','{"blocks":[{"type":"text","text":"يعالج الدرس سير عمل إنتاج الخرائط الجوية ضمن بيئة مركز أرصاد يعمل على مدار الساعة ويقدم معلومات لقطاعات متعددة."},{"type":"text","text":"الهدف التشغيلي: مصادر البيانات والتحليل والإخراج والمراجعة. مع ضمان وضوح المسؤوليات واستمرارية المعلومات وسلامة القرار."},{"type":"text","text":"تحدد بداية الإجراء المسؤوليات والأدوار ومصادر البيانات والمنتج المطلوب والمهلة الزمنية."},{"type":"text","text":"تجمع الحالة من الرصد السطحي والعلوي والرادار والأقمار والنماذج والسجلات التشغيلية."},{"type":"text","text":"تسجل الافتراضات والقيود والسيناريوهات البديلة ومستوى الثقة وأسباب القرار."},{"type":"text","text":"تستخدم قوالب موحدة للمصطلحات والتوقيت والوحدات والمناطق لتقليل الالتباس بين الفرق."},{"type":"text","text":"تطبق مراجعة زميل أو مسؤول مناوبة على المنتجات ذات الأثر العالي قبل إصدارها وفق الإجراء المعتمد."},{"type":"text","text":"تحفظ نسخة مؤرخة من المنتج والبيانات المرجعية وسجل التغييرات لتسهيل التدقيق اللاحق."},{"type":"text","text":"تحدد آلية التصعيد عند ظهور معلومات جديدة أو تعارض بين مصادر البيانات أو تعطل خدمة أساسية."},{"type":"text","text":"تراجع مؤشرات الأداء والالتزام بالوقت وجودة المحتوى ورضا الجهات المستفيدة بصورة دورية."},{"type":"text","text":"مثال تطبيقي: عند تغير مسار حالة جوية، يوثق المتنبئ الدليل الجديد ويحدث السيناريو والمنتج ويبلغ المناوبة والجهات المعنية."},{"type":"callout","text":"الخلاصة: التشغيل الاحترافي يعتمد على إجراء موحد وتواصل موثق ومراجعة مستمرة واستمرارية الخدمة."}]}',3020,50,'["تحديد الأدوار ومصادر المعلومات","إنتاج مخرجات موحدة قابلة للتدقيق","تطبيق المراجعة والتحسين التشغيلي"]','إجراءات العمل والتحليل اليومي'),
